    ('data/objects_config.json', 'line 534: "about": "The crust is thin compared wit', '            "description": "Earth\'s thin, solid outer skin: the ground we live on, the ocean floors, and everything that has ever lived.",\n            "about": "The crust is thin compared with the planet: 5 to 10 km under the oceans, where it is mostly basalt, and 30 to 50 km under the continents, where it is mostly granite. Surface temperatures range from about minus 80 to 60 degrees Celsius. It holds all known life and every resource we can reach.",\n            "radius": {\n', '            "description": "Earth\'s thin, solid outer skin: the ground we live on, the ocean floors, and everything that has ever lived.",\n            "about": "The crust is thin compared with the planet: about {oceanic} km under the oceans, where it is mostly basalt, and about {continental} km on average under land, where it is mostly granite. The coldest temperature measured at the surface is {coldest} kelvin, at Vostok in Antarctica, and the hottest is {hottest} kelvin, at Furnace Creek in California. It holds all known life and every resource we can reach.",\n            "radius": {\n', 1),
    ('data/objects_config.json', 'line 541: "oceanic": { "value": 5, "unit": "km", "', '            },\n            "info_url": "https://en.wikipedia.org/wiki/Earth%27s_crust",\n', '            },\n            "oceanic": { "value": 5, "unit": "km", "orrery_constant": "constants_new.py::EARTH_CRUST_OCEANIC_THICKNESS_KM" },\n            "continental": { "value": 30, "unit": "km", "orrery_constant": "constants_new.py::EARTH_CRUST_CONTINENTAL_THICKNESS_KM" },\n            "coldest": { "value": 184.0, "unit": "k", "orrery_constant": "constants_new.py::EARTH_SURFACE_COLDEST_K" },\n            "hottest": { "value": 329.8, "unit": "k", "orrery_constant": "constants_new.py::EARTH_SURFACE_HOTTEST_K" },\n            "info_url": "https://en.wikipedia.org/wiki/Earth%27s_crust",\n', 1),
    ('data/objects_config.json', 'line 551: "source_note": "The Earth radius used as', '            "source": "NASA Planetary Fact Sheet, Earth -- volumetric mean radius",\n            "source_note": "The Earth radius used as the unit stays the IAU\'s equatorial one: Prsa et al. (2016), AJ 152:41, on IAU 2015 Resolution B3.",\n            "orrery_constant": "constants_new.py::EARTH_MEAN_RADIUS_KM",\n', '            "source": "NASA Planetary Fact Sheet, Earth -- volumetric mean radius",\n            "orrery_constant": "constants_new.py::EARTH_MEAN_RADIUS_KM",\n', 1),
    ('data/objects_config.json', 'line 552: "note": "Drawn at the mean radius, the s', '            "orrery_constant": "constants_new.py::EARTH_MEAN_RADIUS_KM",\n            "note": "Drawn at the mean radius, the sphere the interior layers (PREM) are measured against. Crust thickness (5-10 km oceanic, 30-50 km continental) is below the drawn resolution.",\n            "radius_note": "This is Earth\'s mean radius: the radius of a ball with the same volume as the smooth, slightly flattened shape fitted to sea level. The Earth radius used as a unit here is the equatorial radius, as the International Astronomical Union recommends, so the mean radius is a little less than one. The ground itself rises and falls from this by kilometres."\n', '            "orrery_constant": "constants_new.py::EARTH_MEAN_RADIUS_KM",\n            "note": "Drawn at the mean radius, the sphere the interior layers are measured against. The crust itself is too thin to show at this scale.",\n            "radius_note": "This is Earth\'s mean radius: the radius of a ball with the same volume as the smooth, slightly flattened shape fitted to sea level. The Earth radius used as a unit here is the equatorial radius, as the International Astronomical Union recommends, so the mean radius is a little less than one. The ground itself rises and falls from this by kilometres."\n', 1),
    ('data/objects_config.json', 'line 569: "about": "The troposphere, on average th', '            "description": "The air where weather happens and the ozone layer sits: the troposphere and stratosphere, holding nearly all the atmosphere\'s mass.",\n            "about": "The troposphere, the lowest 12 km or so, is where clouds and weather form; above it the stratosphere, to about 50 km, holds the ozone layer. Together they contain 99 percent of the atmosphere\'s mass, mostly nitrogen and oxygen. Temperature falls from about 15 degrees Celsius at sea level to minus 60 at the top of the troposphere, then warms again toward the stratopause as ozone absorbs sunlight.",\n            "radius": {\n', '            "description": "The air where weather happens and the ozone layer sits: the troposphere and stratosphere, holding nearly all the atmosphere\'s mass.",\n            "about": "The troposphere, on average the lowest {troposphere} km, is where clouds and weather form; above it the stratosphere, to about {altitude} km, holds the ozone layer. Together they hold more than {mass_share} percent of the atmosphere\'s mass, mostly nitrogen and oxygen. Temperature falls from an average of about {surface} kelvin at the surface to about {tropopause} kelvin at the top of the troposphere, then warms again toward the stratopause as ozone absorbs sunlight.",\n            "radius": {\n', 1),
    ('data/objects_config.json', 'line 584: "troposphere": { "value": 12, "unit": "k', '            },\n            "info_url": "https://science.nasa.gov/earth/earth-atmosphere/earths-atmosphere-a-multi-layered-cake/",\n', '            },\n            "troposphere": { "value": 12, "unit": "km", "orrery_constant": "constants_new.py::EARTH_TROPOPAUSE_ALTITUDE_KM" },\n            "surface": { "value": 290, "unit": "k", "orrery_constant": "constants_new.py::EARTH_SURFACE_MEAN_TEMPERATURE_K" },\n            "tropopause": { "value": 222, "unit": "k", "orrery_constant": "constants_new.py::EARTH_TROPOPAUSE_TEMPERATURE_K" },\n            "mass_share": { "value": 99, "unit": "percent", "orrery_constant": "constants_new.py::EARTH_ATMOSPHERE_MASS_BELOW_STRATOPAUSE_PERCENT" },\n            "info_url": "https://science.nasa.gov/earth/earth-atmosphere/earths-atmosphere-a-multi-layered-cake/",\n', 1),
    ('data/objects_config.json', 'line 594: "orrery_constant": "constants_new.py::EA', '            "source": "IERS Conventions (2010), Petit & Luzum (eds.), IERS Technical Note No. 36, Table 1.1; NOAA JetStream, \\"Layers of the Atmosphere\\" -- stratosphere to about 50 km; and NASA, \\"Earth\'s Atmospheric Layers\\" -- the stratosphere extends to 50 km.",\n            "orrery_constant": "constants_new.py::EARTH_STRATOPAUSE_RADIUS_KM",\n            "note": "Troposphere and stratosphere, 99% of atmospheric mass. Drawn at the physical boundary since 2026-09-07 (L-295); before that at a visibility fraction its own hover contradicted."\n          },\n', '            "source": "IERS Conventions (2010), Petit & Luzum (eds.), IERS Technical Note No. 36, Table 1.1; NOAA JetStream, \\"Layers of the Atmosphere\\" -- stratosphere to about 50 km; and NASA, \\"Earth\'s Atmospheric Layers\\" -- the stratosphere extends to 50 km.",\n            "orrery_constant": "constants_new.py::EARTH_STRATOPAUSE_RADIUS_KM"\n          },\n', 1),
    ('data/objects_config.json', 'line 599: "about": "Above {stratopause} km lie the', '            "description": "The thin upper air where meteors burn up, the aurora glows, and the Space Station orbits, fading toward space.",\n            "about": "Above 50 km lie the mesosphere, where most meteors burn up, the thermosphere, where the aurora appears and the International Space Station flies, and, higher still, the beginning of the exosphere. In the thermosphere the gas can reach 2,000 degrees Celsius, yet it is so thin it would feel cold to the skin.",\n            "radius": {\n', '            "description": "The thin upper air where meteors burn up, the aurora glows, and the Space Station orbits, fading toward space.",\n            "about": "Above {stratopause} km lie the mesosphere, where most meteors burn up, the thermosphere, where the aurora appears and the International Space Station flies, and, higher still, the beginning of the exosphere. In the thermosphere the gas can reach about {thermosphere} kelvin, yet it is so thin it would feel cold to the skin.",\n            "radius": {\n', 1),
    ('data/objects_config.json', 'line 614: "stratopause": { "value": 50, "unit": "k', '            },\n            "info_url": "https://www.nasa.gov/image-article/earths-upper-atmosphere/",\n', '            },\n            "stratopause": { "value": 50, "unit": "km", "orrery_constant": "constants_new.py::EARTH_STRATOPAUSE_ALTITUDE_KM" },\n            "thermosphere": { "value": 2000, "unit": "k", "orrery_constant": "constants_new.py::EARTH_THERMOSPHERE_TOP_TEMPERATURE_K" },\n            "thermopause_low": { "value": 500, "unit": "km", "orrery_constant": "constants_new.py::EARTH_THERMOPAUSE_LOW_KM" },\n            "thermopause_high": { "value": 1000, "unit": "km", "orrery_constant": "constants_new.py::EARTH_THERMOPAUSE_HIGH_KM" },\n            "info_url": "https://www.nasa.gov/image-article/earths-upper-atmosphere/",\n', 1),
    ('data/objects_config.json', 'line 625: "note": "Drawn at a nominal top of {alti', '            "orrery_constant": "constants_new.py::EARTH_THERMOPAUSE_RADIUS_KM",\n            "note": "Mesosphere and thermosphere. The thermopause moves with solar activity over roughly 500-1,000 km; 600 km is the nominal figure."\n          },\n', '            "orrery_constant": "constants_new.py::EARTH_THERMOPAUSE_RADIUS_KM",\n            "note": "Drawn at a nominal top of {altitude} km. The real top, the thermopause, lies anywhere between about {thermopause_low} and {thermopause_high} km, rising and falling with the energy coming from the Sun."\n          },\n', 1),
    ('data/objects_config.json', 'line 677: "name": "Low Earth Orbit, inner edge",', '          "leo_inner": {\n            "name": "Low Earth Orbit, inner edge (180 km)",\n            "description": "The lower edge of low Earth orbit, the band of space where most satellites and the Space Station fly.",\n', '          "leo_inner": {\n            "name": "Low Earth Orbit, inner edge",\n            "description": "The lower edge of low Earth orbit, the band of space where most satellites and the Space Station fly.",\n', 1),
    ('data/objects_config.json', 'line 679: "about": "Low Earth orbit is the region ', '            "description": "The lower edge of low Earth orbit, the band of space where most satellites and the Space Station fly.",\n            "about": "Low Earth orbit is the region from roughly 180 to 2,000 km up. Satellites there circle at every angle to the equator, so together they form a shell around Earth rather than a ring, and each completes an orbit in about 90 to 120 minutes. The International Space Station, the Hubble Space Telescope, Starlink and most weather and Earth-observing satellites live here; the moving lights seen at dusk and dawn are usually these.",\n            "radius": {\n', '            "description": "The lower edge of low Earth orbit, the band of space where most satellites and the Space Station fly.",\n            "about": "Low Earth orbit is the region from about {altitude} to {upper} km up. Satellites there circle at every angle to the equator, so together they form a shell around Earth rather than a ring, and each completes an orbit in about {period_low} to {period_high} minutes. The International Space Station, the Hubble Space Telescope, Starlink and most weather and Earth-observing satellites live here; the moving lights seen at dusk and dawn are usually these.",\n            "radius": {\n', 1),
    ('data/objects_config.json', 'line 703: "upper": { "value": 2000, "unit": "km", ', '              "source": "ESA, \\"Types of orbits\\" (2020), section \\"Low Earth orbit (LEO)\\", https://www.esa.int/Our_Activities/Launchers/Types_of_orbits -- the lower limit for how low a satellite can fly is down to the impact of Earth\'s atmosphere; generally, satellites do not fly below 180 km for this reason."\n            },\n            "info_url": "https://en.wikipedia.org/wiki/Low_Earth_orbit",\n            "color": "rgb(255, 248, 220)",\n', '              "source": "ESA, \\"Types of orbits\\" (2020), section \\"Low Earth orbit (LEO)\\", https://www.esa.int/Our_Activities/Launchers/Types_of_orbits -- the lower limit for how low a satellite can fly is down to the impact of Earth\'s atmosphere; generally, satellites do not fly below 180 km for this reason."\n            },\n            "upper": { "value": 2000, "unit": "km", "orrery_constant": "constants_new.py::EARTH_LEO_UPPER_ALTITUDE_KM" },\n            "period_low": { "value": 88, "unit": "min", "orrery_constant": "constants_new.py::EARTH_LEO_INNER_PERIOD_MIN" },\n            "period_high": { "value": 127, "unit": "min", "orrery_constant": "constants_new.py::EARTH_LEO_OUTER_PERIOD_MIN" },\n            "info_url": "https://en.wikipedia.org/wiki/Low_Earth_orbit",\n            "color": "rgb(255, 248, 220)",\n', 1),
    ('data/objects_config.json', 'line 716: "name": "Low Earth Orbit, outer edge", "', '          "leo_outer": {\n            "name": "Low Earth Orbit, outer edge (2,000 km)",\n            "description": "The upper edge of low Earth orbit, about 2,000 km up, above which the sky belongs to higher orbits.",\n            "about": "Low Earth orbit is the region from roughly 180 to 2,000 km up. Satellites there circle at every angle to the equator, so together they form a shell around Earth rather than a ring, and each completes an orbit in about 90 to 120 minutes. The International Space Station, the Hubble Space Telescope, Starlink and most weather and Earth-observing satellites live here; the moving lights seen at dusk and dawn are usually these.",\n            "radius": {\n', '          "leo_outer": {\n            "name": "Low Earth Orbit, outer edge",\n            "description": "The upper edge of low Earth orbit, about {altitude} km up, above which the sky belongs to higher orbits.",\n            "about": "Low Earth orbit is the region from about {lower} to {altitude} km up. Satellites there circle at every angle to the equator, so together they form a shell around Earth rather than a ring, and each completes an orbit in about {period_low} to {period_high} minutes. The International Space Station, the Hubble Space Telescope, Starlink and most weather and Earth-observing satellites live here; the moving lights seen at dusk and dawn are usually these.",\n            "radius": {\n', 1),
    ('data/objects_config.json', 'line 742: "lower": { "value": 180, "unit": "km", "', '            },\n            "info_url": "https://en.wikipedia.org/wiki/Low_Earth_orbit",\n', '            },\n            "lower": { "value": 180, "unit": "km", "orrery_constant": "constants_new.py::EARTH_LEO_LOWER_ALTITUDE_KM" },\n            "period_low": { "value": 88, "unit": "min", "orrery_constant": "constants_new.py::EARTH_LEO_INNER_PERIOD_MIN" },\n            "period_high": { "value": 127, "unit": "min", "orrery_constant": "constants_new.py::EARTH_LEO_OUTER_PERIOD_MIN" },\n            "info_url": "https://en.wikipedia.org/wiki/Low_Earth_orbit",\n', 1),
    ('data/objects_config.json', 'line 766: "description": "A ring of satellites abo', '            "name": "Geostationary Belt (GEO)",\n            "description": "A ring of satellites 35,786 km above the equator that circle exactly as fast as Earth turns, so each hangs over one spot.",\n            "about": "Satellites in the geostationary belt orbit once a day, matching Earth\'s rotation, and so stay fixed over a point on the equator. Several hundred of them carry television, weather imagery and communications for much of the world. In April 2029 the asteroid Apophis will pass inside this ring, a few thousand kilometers below the nearest satellites.",\n            "shape": "equatorial_ring",\n', '            "name": "Geostationary Belt (GEO)",\n            "description": "A ring of satellites above the equator that circle exactly as fast as Earth turns, so each hangs over one spot.",\n            "about": "Satellites in the geostationary belt orbit once a day, matching Earth\'s rotation, and so stay fixed over a point on the equator. Several hundred of them carry television, weather imagery and communications for much of the world. In April 2029 the asteroid Apophis will pass about {apophis} km above Earth\'s surface, inside this ring and closer than many of its satellites.",\n            "shape": "equatorial_ring",\n', 1),
    ('data/objects_config.json', 'line 783: "apophis": { "value": 32000, "unit": "km', '            },\n            "info_url": "https://en.wikipedia.org/wiki/Geostationary_orbit",\n', '            },\n            "apophis": { "value": 32000, "unit": "km", "orrery_constant": "constants_new.py::APOPHIS_2029_APPROACH_ALTITUDE_KM" },\n            "info_url": "https://en.wikipedia.org/wiki/Geostationary_orbit",\n', 1),
    ('data/objects_config.json', 'line 792: "note": "Drawn tilted with Earth\'s equat', '            "orrery_constant": "constants_new.py::EARTH_GEOSTATIONARY_RADIUS_KM",\n            "note": "A ring in the equatorial plane, not a sphere, tilted with Earth\'s equator by the served pole. 42,164 km from Earth\'s centre, 35,786 km up."\n          },\n', '            "orrery_constant": "constants_new.py::EARTH_GEOSTATIONARY_RADIUS_KM",\n            "note": "Drawn tilted with Earth\'s equator."\n          },\n', 1),
    ('data/objects_config.json', 'line 809: "about": "Earth\'s magnetic field carves ', '            "description": "The outer boundary of Earth\'s magnetic field, where it holds off the solar wind: pressed in by day, trailing a long tail by night.",\n            "about": "Earth\'s magnetic field carves a cavity in the solar wind called the magnetosphere. On the side facing the Sun the wind presses it in; on the night side it stretches into a magnetotail observed far beyond the Moon\'s distance. The magnetopause is that boundary. It deflects the solar wind and turns aside many of the charged particles that reach Earth from the Sun and from beyond the solar system. The surface drawn is a model for a quiet solar wind; the real boundary moves in and out as the wind\'s pressure changes.",\n            "shape": "magnetopause",\n', '            "description": "The outer boundary of Earth\'s magnetic field, where it holds off the solar wind: pressed in by day, trailing a long tail by night.",\n            "about": "Earth\'s magnetic field carves a cavity in the solar wind called the magnetosphere. On the side facing the Sun the wind presses it in; on the night side it stretches into a magnetotail observed far beyond the Moon\'s distance. The magnetopause is that boundary. It deflects the solar wind and turns aside many of the charged particles that reach Earth from the Sun and from beyond the solar system. The surface drawn is a model for a quiet solar wind; the real boundary moves in and out as the wind\'s pressure changes. In a strong storm the wind can push it inside the geostationary ring: on 21 January 2005 its nose came within about {storm} Earth radii of Earth\'s centre.",\n            "shape": "magnetopause",\n', 1),
    ('data/objects_config.json', 'line 812: "_model": "Shue et al. (1998) eq. 10 wit', '            "surface": {\n              "_model": "Shue et al. (1998) eq. 10 with eq. 11. r = r0 [2 / (1 + cos theta)]^alpha, theta measured from the Sun-Earth line, r0 the standoff below. The geometry evaluates alpha = (a6 + a7 Bz)(1 + a8 ln Dp) from the rows here; alpha gets no row of its own because no text on the page prints it. At the declared conditions alpha is 0.59 -- two figures, because a6 is 0.58 +/- 0.01 and that carries straight through.",\n              "a6": {\n', '            "surface": {\n              "_model": "Shue et al. (1998) eq. 10 with eq. 11. r = r0 [2 / (1 + cos theta)]^alpha, theta measured from the Sun-Earth line, r0 the standoff below. The flaring exponent is alpha = (a6 + a7 Bz)(1 + a8 ln Dp), with the paper\'s fitted a6, a7 and a8 (its Table 1), at the solar wind chosen for the picture.",\n              "a6": {\n', 1),
    ('data/objects_config.json', 'line 870: "storm": { "value": 3, "unit": "r_earth"', '            "scatter": {"hover_line": "Spacecraft that cross the real boundary typically find it within {value} Earth radii of this model.", "value": 1.23, "unit": "r_earth", "in": {"au": {"value": 5.2e-05, "figures": 2, "prints": null}, "km": {"value": 7800.0, "figures": 2, "prints": null}, "pc": {"value": 2.54e-10, "figures": 3, "prints": null}, "r_earth": {"value": 1.23, "figures": 3, "prints": null}, "r_sun": {"value": 0.0113, "figures": 3, "prints": null}}, "figures": 3, "orrery_constant": "constants_new.py::EARTH_MAGNETOPAUSE_SHUE_SCATTER_RADII", "source": "Shue et al. (1998), doi:10.1029/98JA01103, p. 17,697 -- the improved model\'s standard deviation against the observed magnetopause crossings it was fitted to is 1.23 R_E."},\n            "info_url": "https://en.wikipedia.org/wiki/Magnetopause",\n', '            "scatter": {"hover_line": "Spacecraft that cross the real boundary typically find it within {value} Earth radii of this model.", "value": 1.23, "unit": "r_earth", "in": {"au": {"value": 5.2e-05, "figures": 2, "prints": null}, "km": {"value": 7800.0, "figures": 2, "prints": null}, "pc": {"value": 2.54e-10, "figures": 3, "prints": null}, "r_earth": {"value": 1.23, "figures": 3, "prints": null}, "r_sun": {"value": 0.0113, "figures": 3, "prints": null}}, "figures": 3, "orrery_constant": "constants_new.py::EARTH_MAGNETOPAUSE_SHUE_SCATTER_RADII", "source": "Shue et al. (1998), doi:10.1029/98JA01103, p. 17,697 -- the improved model\'s standard deviation against the observed magnetopause crossings it was fitted to is 1.23 R_E."},\n            "storm": { "value": 3, "unit": "r_earth", "orrery_constant": "constants_new.py::EARTH_MAGNETOPAUSE_STORM_2005_RADII" },\n            "info_url": "https://en.wikipedia.org/wiki/Magnetopause",\n', 1),
    ('data/objects_config.json', 'line 878: "orrery_constant": "constants_new.py::EA', '            "source_note": "Shue\'s eq. 10, worked out at the solar wind chosen for the picture.",\n            "orrery_constant": "constants_new.py::EARTH_MAGNETOPAUSE_STANDOFF_RADII",\n            "note": "Quiet-time nominal. Under storm compression it can fall inside geostationary orbit (6.6 R_E)."\n          },\n', '            "source_note": "Shue\'s eq. 10, worked out at the solar wind chosen for the picture.",\n            "orrery_constant": "constants_new.py::EARTH_MAGNETOPAUSE_STANDOFF_RADII"\n          },\n', 1),
